#include <stack>
#include <iostream>

void safe_pop_print(std::stack<int>& st) {
    if (!st.empty()) { // Mandatory safety check
        std::cout << st.top() << " ";
        st.pop();
    } else {
        std::cerr << "Stack is empty, skip operation.\n";
    }
}

int main() {
    std::stack<int> s;
    // s.pop(); // DANGER: Undefined Behavior if uncommented!
    safe_pop_print(s);
    s.push(42);
    safe_pop_print(s);
}
